import {ACTIONS,keyLabel} from './controls.js';
import {EFFECT_PRESETS} from './graphics.js';
import {benchmarkReportHTML} from './graphics-benchmark.js';

export const SETTINGS_CATEGORIES=['Controls','Aim','HUD','Graphics','Audio','Help'];
export const SETTINGS_SECTIONS={Controls:['General','Movement','Combat','Weapons','Game','Look keys'],Aim:['General'],HUD:['Layout','Minimap','Comfort'],Graphics:['Quality','Lighting','Image','Smoothing','Performance'],Audio:['Mix'],Help:['Support','Practice','Resets']};
export const SETTINGS_AA_PRESETS={standard:{msaa:2,aaFilter:'none',taa:false},high:{msaa:4,aaFilter:'none',taa:false},smaa:{msaa:0,aaFilter:'smaa',taa:false},hybrid:{msaa:2,aaFilter:'smaa',taa:false},fxaa:{msaa:0,aaFilter:'fxaa',taa:false},temporal:{msaa:0,aaFilter:'none',taa:true}};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const select=(scope,key,label,choices,hint='',id)=>({scope,key,label,choices:choices.map(c=>Array.isArray(c)?c:[c,c]),hint,id,type:'select'});
const range=(scope,key,label,min,max,step,unit='%',hint='',id)=>({scope,key,label,min,max,step,unit,hint,id,type:'range'});
const toggle=(scope,key,label,hint='',id)=>({scope,key,label,hint,id,type:'toggle'});
const action=(key,label,hint='')=>({key,label,hint,type:'action'});
export const settingID=row=>row.id||`${row.scope==='touch'?'touch-setting':'setting'}-${row.key}`;
export const settingOutputID=row=>`${row.scope==='touch'?'touch-value':'value'}-${row.key}`;
export const settingValueText=(row,value)=>row.unit==='×'?Number(value).toFixed(2)+'×':row.unit==='°'?Math.round(value)+'°':Math.round(value*100)+'%';
export function settingsRows(category,section,input='Keyboard'){
 if(category==='Controls')return input==='Touch'?[select('touch','fireMode','Firing mode',[['simple','Simple · auto-fire'],['manual','Manual']],'Works with every weapon, including charged launchers.'),toggle('touch','manualFire','Hip-fire button','Fire immediately, without entering sights.'),toggle('touch','holdSemi','Hold to repeat semi-auto'),select('touch','stickMode','Movement stick',[['floating','Floating'],['fixed','Fixed']]),select('touch','focusMode','Slow motion',[['toggle','Tap to toggle'],['hold','Hold']])]:[toggle('game','holdSemi','Hold to repeat semi-auto','','control-hold-semi'),select('game','crouchToggle','Crouch behavior',[['hold','Hold'],['toggle','Toggle']],'','control-crouch'),action('bindings','Key bindings','Every action, primary and secondary bindings.')];
 if(category==='Aim')return input==='Touch'?[range('touch','sensitivity','Look sensitivity',.3,2.5,.05),range('touch','vertical','Vertical sensitivity',.5,1.5,.05),toggle('touch','aimAssist','Aim slowdown','Slows your swipe near a visible target. You stay in control.'),toggle('touch','invertY','Invert vertical aim'),select('touch','gyro','Gyroscope',[['off','Off'],['always','Always']],'Optional tilt aiming. Touch aim always works.'),range('touch','gyroSensitivity','Gyro sensitivity',.2,2,.05),action('gyro','Enable motion access / recenter','Motion permission and availability remain explicit.')]:[range('game','sensitivity','Mouse sensitivity',.2,3,.05,'×','','control-sensitivity'),toggle('game','invertY','Invert mouse Y','','control-invert')];
 if(category==='HUD'){
  if(section==='Layout')return input==='Touch'?[select('touch','preset','Touch layout',[['thumbs','Two thumbs'],['claw','Four fingers'],['left','Left handed']]),range('touch','controlScale','Control size',.7,1.4,.05),range('touch','controlOpacity','Control opacity',.2,1,.05),action('editor','Edit individual controls','Drag, resize, fade, hide and nudge. Each preset keeps its own layout.')]:[range('game','hudScale','HUD size',.5,2,.05),action('bindings','Change key bindings','Movement, combat, weapons and menu actions.')];
  if(section==='Minimap')return[toggle('game','minimap','Show minimap'),toggle('game','minimapNorth','Keep north at the top'),...(input==='Touch'?[action('editor-minimap','Move and resize minimap','Select the minimap in the HUD editor.')]:[range('game','minimapScale','Minimap size',.5,2,.05,'%','Screen size changes; map range stays the same.')])];
  return[range('game','motion','Camera motion',0,1,.05,'%','Adjust weapon sway, camera kick and movement effects.')];
 }
 if(category==='Audio')return['guns','steps','feedback','music'].map((key,i)=>range('game',key,['Gunfire','Footsteps','Hit & damage feedback','Music'][i],0,1,.05));
 if(category==='Graphics'){
  if(section==='Quality')return[select('effects','effects','Effects quality',[['battery','Battery saver'],['balanced','Balanced'],['high','High detail'],['custom','Custom']],'Leaves resolution and edge smoothing unchanged.'),select('aa','resolutionScale','Render resolution',[[.25,'25%'],[.33,'33%'],[.5,'50%'],[.67,'67%'],[.75,'75%'],[1,'Native · 100%']],'HUD and text remain sharp.'),range('graphics','fov','Field of view',65,110,1,'°'),action('smoothing','Edge smoothing','Geometry samples, filters and temporal smoothing.')];
  if(section==='Lighting')return[select('graphics','shadowQuality','Shadow detail',[['off','Off'],['low','Low · 512'],['medium','Medium · 1024'],['high','High · 2048']]),select('graphics','shadowFilter','Shadow filtering',[['hard','Hard'],['pcf','Smooth'],['soft','Soft']]),select('graphics','aoQuality','Contact shading',[['off','Off'],['low','Low'],['medium','Medium'],['high','High']],'Ambient occlusion'),range('graphics','aoStrength','Contact shading strength',0,1,.05),range('graphics','bloomStrength','Bloom',0,2,.05)];
  if(section==='Image')return[toggle('graphics','pixelForge','Pixel Forge','Textures the environment; keeps weapons and characters clean.'),range('graphics','pixelForgeIntensity','Pixel Forge intensity',0,1,.01),range('graphics','exposure','Brightness',.5,1.5,.05),select('graphics','toneMap','Tone mapping',[['cinematic','Cinematic'],['neutral','Neutral'],['none','Off']]),range('graphics','vignette','Vignette',0,2,.05),toggle('graphics','grain','Film grain','Used when Pixel Forge is off.'),toggle('graphics','colorGrade','Color grading')];
  if(section==='Smoothing')return[toggle('aa','antialias','Edge smoothing','Antialiasing. Resolution remains independent.'),select('aa','aaPreset','Quick comparison',[['custom','Custom'],['standard','2× MSAA · default'],['high','4× MSAA'],['smaa','SMAA only'],['hybrid','2× MSAA + SMAA'],['fxaa','FXAA only'],['temporal','TAA only · experimental']]),select('aa','msaa','Geometry samples',[[0,'Off'],[2,'2× MSAA'],[4,'4× MSAA']]),select('aa','aaFilter','Finishing filter',[['none','Off'],['fxaa','FXAA'],['smaa','SMAA']]),toggle('aa','taa','Temporal smoothing','Experimental. Moving characters may trail; sights and HUD stay clean.')];
  return[toggle('aa','aaStats','Show performance'),action('benchmark','Run graphics benchmark','About 45 seconds plus loading. Three maps, six combat scenes.'),action('report','View saved benchmark','FPS, 1% lows and detailed frame-time percentiles.')];
 }
 if(category==='Help'){
  if(section==='Practice')return[action('practice','Open practice','Try settings without changing your saved run.'),action('maps','Practice maps','Choose any available arena.'),action('workbench','Weapon workbench','Try every weapon, attachment and sight.'),action('end-practice','End practice','Return to the main menu; your run stays intact.')];
  if(section==='Resets')return[action('reset-touch','Reset all touch settings','Restores touch preferences; keeps saved control layouts.'),action('reset-graphics','Reset all graphics','Restores display defaults; leaves controls and audio intact.'),action('reset-bindings','Reset all key bindings','Restores primary and secondary defaults.')];
  return[action('guide','How to play','Movement, aiming, firing, focus and killstreaks.'),action('display-report','Copy display report','Display, viewport and device diagnostics.'),action('install','Play as an installed app','Installation help; playing in the browser stays available.')];
 }
 return[];
}
export function settingsSections(category,input){return category==='Controls'&&input==='Touch'?['General']:SETTINGS_SECTIONS[category]||['General'];}
export function matchedAAPreset(settings){return Object.entries(SETTINGS_AA_PRESETS).find(([,p])=>Object.entries(p).every(([k,v])=>settings[k]===v))?.[0]||'custom';}
export function rowValue(row,s){if(row.scope==='touch')return s.touchSettings[row.key];if(row.scope==='effects')return Object.entries(EFFECT_PRESETS).find(([,p])=>Object.entries(p).every(([k,v])=>s.settings[k]===v))?.[0]||'custom';if(row.key==='aaPreset')return matchedAAPreset(s.settings);if(row.key==='crouchToggle')return s.settings.crouchToggle?'toggle':'hold';return s.settings[row.key];}
export function settingsRowHTML(row,s){
 if(row.type==='action')return `<button type="button" class="sw-action" data-settings-action="${row.key}" ${(!s.touch&&['editor','editor-minimap','gyro','reset-touch'].includes(row.key))||!s.practice&&['end-practice','workbench','maps'].includes(row.key)?'disabled':''}><span>${esc(row.label)}${row.hint?`<small>${esc(row.hint)}</small>`:''}</span><span aria-hidden="true">↗</span></button>`;
 const value=rowValue(row,s),id=settingID(row),output=settingOutputID(row),disabled=row.scope==='aa'&&['aaPreset','msaa','aaFilter','taa'].includes(row.key)&&!s.settings.antialias;
 const attributes=`id="${id}" ${row.scope==='graphics'?`data-graphics="${row.key}"`:row.scope==='effects'?'data-graphics-preset':`data-workspace-setting="${row.scope}:${row.key}"`} ${disabled?'disabled':''}`;
 let control='';if(row.type==='select')control=`<select ${attributes} aria-label="${esc(row.label)}">${row.choices.map(([v,label])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(label)}</option>`).join('')}</select>`;
 if(row.type==='toggle')control=`<input ${attributes} type="checkbox" role="switch" ${value?'checked':''}>`;
 if(row.type==='range')control=`<span class="sw-slider"><output id="${output}" for="${id}" ${row.scope==='graphics'?`data-graphics-value="${row.key}"`:''}>${settingValueText(row,value)}</output><input ${attributes} type="range" min="${row.min}" max="${row.max}" step="${row.step}" value="${value}" aria-valuetext="${settingValueText(row,value)}" style="--fill:${(value-row.min)/(row.max-row.min)*100}%"></span>`;
 return `<label class="sw-row" for="${id}"><span class="sw-label">${esc(row.label)}${row.hint?`<small>${esc(row.hint)}</small>`:''}</span>${control}</label>`;
}
const icons={Controls:'M5 7h14l3 10-4 1-3-4H9l-3 4-4-1ZM7 9v4m-2-2h4m7 0h1m2-2h1',Aim:'M12 2v5m0 10v5M2 12h5m10 0h5M12 5a7 7 0 1 0 0 14 7 7 0 0 0 0-14',HUD:'M3 3h7v9H3Zm11 0h7v5h-7Zm0 9h7v9h-7ZM3 16h7v5H3Z',Graphics:'M3 4h18v13H3Zm5 17h8m-4-4v4',Audio:'M3 9h4l5-5v16l-5-5H3Zm13-2c3 3 3 7 0 10m3-13c5 5 5 11 0 16',Help:'M10 8a3 3 0 1 1 4 3c-2 1-2 2-2 3m0 3v1M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20'};
const icon=category=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[category]}"/></svg>`;
const copy={Controls:['MAKE IT FEEL NATURAL','Test your controls','Choose how you fire and move. Automatic fire keeps the same weapon timing as manual input.'],Aim:['MAKE EVERY SHOT YOURS','Test your aim','Touch and mouse tuning are separate. Gyro permission never blocks ordinary aiming.'],HUD:['PUT IT WITHIN REACH','Your HUD, in place','Each touch preset keeps its own positions, sizes and opacity. Test layouts in practice.'],Graphics:['MAKE IT LOOK RIGHT','Check the view','Effects, resolution and edge smoothing stay independent. This is your current rendered view.'],Audio:['HEAR WHAT MATTERS','Listen to the mix','Gunfire, footsteps, hit feedback and music keep independent volume controls.'],Help:['GET BACK INTO IT','Practice and support','Find practice tools, instructions, installation help and display diagnostics.']};
function bindingHTML(s){const group=s.section,actions=ACTIONS.filter(a=>a.group===group);return `<div class="sw-binding-head"><span>Action</span><span>Primary</span><span>Secondary</span></div>${actions.map(a=>`<div class="sw-binding-row"><span>${esc(a.label)}</span>${s.controls.bindings[a.id].map((key,i)=>`<button type="button" data-binding="${a.id}:${i}" aria-pressed="${s.bindingPending?.id===a.id&&s.bindingPending.slot===i}" aria-label="${esc(a.label)}, ${i?'secondary':'primary'}: ${keyLabel(key)}">${keyLabel(key)}</button>`).join('')}</div>`).join('')}`;}
function bindingPrompt(s){const p=s.bindingPending;if(!p)return'';return `<section class="sw-binding-prompt" aria-label="Assign key binding"><b>${esc(ACTIONS.find(a=>a.id===p.id).label)} · ${p.slot?'Secondary':'Primary'}</b><span>${p.code?`${esc(keyLabel(p.code))} is assigned to ${p.conflicts.map(c=>esc(c.label)).join(', ')}. Replace that binding?`:'Press a key, mouse button or wheel. Escape cancels.'}</span><div>${p.code?'<button id="bind-replace" type="button">Replace binding</button>':'<button id="bind-clear" type="button">Clear binding</button><button type="button" data-binding-capture>Click / scroll here to bind mouse</button>'}<button id="bind-escape" type="button">Use Esc</button><button id="bind-cancel" type="button">Cancel</button></div></section>`;}
export function settingsWorkspaceHTML(s){
 const sections=settingsSections(s.category,s.input),bindings=s.category==='Controls'&&s.input==='Keyboard'&&s.section!=='General',rows=bindings?[]:settingsRows(s.category,s.section,s.input);
 const summary=s.aaSummary||'Your current settings';let body=bindings?bindingHTML(s):rows.map(row=>settingsRowHTML(row,s)).join('');
 if(s.category==='Graphics'&&s.section==='Smoothing')body+=`<output id="aa-summary" class="sw-summary" aria-live="polite">${esc(summary)}</output>`;
 if(s.category==='Aim'&&s.input==='Touch')body+=`<p id="gyro-status" class="sw-note">${s.gyroReady?'Motion access is enabled. Recenter in a comfortable position.':'Motion access is optional. Touch aiming always works.'}</p>`;
 if(s.report)body=`<div class="sw-detail-heading"><h3>Saved benchmark</h3><button type="button" data-settings-action="close-detail">Back</button></div>${s.benchmark?benchmarkReportHTML(s.benchmark)+'<button type="button" class="sw-action" data-settings-action="download-report">Download report <span>↗</span></button>':'<p class="sw-note">No saved benchmark yet. Run a benchmark to measure this device.</p>'}`;
 if(s.detail==='install')body='<h3>Play as an installed app</h3><p class="sw-note">On iPhone: Share → Add to Home Screen → Open as Web App. Playing in Safari works too. On Android, use Install app or Add to Home screen in the browser menu.</p>';
 if(s.detail==='guide')body=`<div class="sw-guide">${[['Move & track','Move with the stick or movement keys. Swipe or move the mouse to aim. Keep moving into obstacles to auto-jump on touch.'],['Hold your sights','Track a visible opponent. Simple mode fires when there is a clear shot; manual controls fire on demand.'],['Take control','Use Slow time to steady your aim. Hip fire shoots immediately without entering sights.'],['Stay in the fight','Reload between encounters. Three weapon kills earn a killstreak.']].map(([a,b])=>`<article><h3>${a}</h3><p>${b}</p></article>`).join('')}</div>`;
 if(s.detail==='display')body=`<h3>Display report</h3><p class="sw-note">Clipboard access is unavailable. Select and copy the report below.</p><textarea readonly aria-label="Display report">${esc(s.displayReport)}</textarea>`;
 const [eyebrow,title,description]=copy[s.category],close=s.back==='play'?'Back to game':'Back to menu';
 return `<div role="dialog" aria-modal="true" aria-label="Settings" class="settings-workspace ${s.preview?'sw-preview-open':''}"><header class="sw-header"><div><span class="sw-brand">FRAGONY</span><h1>SETTINGS</h1></div><span class="sw-context">${s.practice?'PRACTICE':s.back==='play'?'PAUSED':'YOUR PREFERENCES'}</span></header><div class="sw-workspace"><nav class="sw-rail" aria-label="Settings categories">${SETTINGS_CATEGORIES.map(category=>`<button type="button" data-settings-category="${category}" ${category===s.category?'aria-current="page"':''}>${icon(category)}<span>${category}</span></button>`).join('')}</nav><main class="sw-main"><div class="sw-title-row"><div><small>${eyebrow}</small><h2>${s.category}</h2></div><button type="button" id="settings-preview-toggle">${s.preview?'Settings':'Preview'}</button>${['Controls','Aim'].includes(s.category)?`<div class="sw-input" role="group" aria-label="Input settings">${['Touch','Keyboard'].map(input=>`<button type="button" data-settings-input="${input}" aria-pressed="${s.input===input}" ${input==='Touch'&&!s.touch?'disabled':''}>${input}</button>`).join('')}</div>`:''}</div>${sections.length>1?`<nav class="sw-subnav" aria-label="${s.category==='Controls'?'Key binding groups':s.category+' sections'}">${sections.map(section=>`<button type="button" data-settings-section="${section}" ${section===s.section?'aria-current="page"':''}>${section==='General'?'General':section==='Look keys'?'Look':section}</button>`).join('')}</nav>`:''}<div class="sw-content"><section class="sw-fields" aria-label="${s.category} settings">${bindingPrompt(s)}${body}</section><aside class="sw-preview"><div class="sw-preview-heading"><span>CURRENT VIEW</span><span>${esc(s.section.toUpperCase())}</span></div><canvas id="settings-preview-canvas" width="480" height="270" aria-label="Current game view with your display settings"></canvas><div class="sw-preview-copy"><h3>${title}</h3><p>${description}</p><button type="button" data-settings-action="practice">Try in practice <span aria-hidden="true">↗</span></button>${s.back==='play'&&!s.practice?'<small>Saves your run. Resume it with Continue from the main menu.</small>':''}</div></aside></div></main></div><footer class="sw-footer"><button type="button" id="settings-reset" ${!bindings&&!rows.some(row=>row.type!=='action')||s.detail||s.report?'disabled':''}>Reset ${bindings?s.section.toLowerCase()+' bindings':(sections.length>1?s.section:s.category).toLowerCase()}</button><span id="settings-status" role="status">${esc(s.message||'Saved on this device')}</span>${s.undo?'<button type="button" id="settings-undo">Undo reset</button>':''}<button type="button" class="sw-primary" id="controls-back">${close}<span aria-hidden="true">→</span></button></footer></div>`;
}
